// A feature's source byline: "<Class> — <Subclass>" (class and subclass names are translated above/below).
I18N_HE_RX.push(
  [/^(.+?) — (.+)$/,(m,tr)=>heClassNames().has(m[1])?`${tr(m[1])} — ${tr(m[2])}`:null],
);

// ================= Barbarian =================
heAdd([
  [`Path of the Berserker`,`נתיב הברסרקר`],
  [`Path of the Ancestral Guardian`,`נתיב שומר האבות`],
  [`Path of the Battlerager`,`נתיב רב-הקרב`],
  [`Path of the Beast`,`נתיב החיה`],
  [`Path of the Giant`,`נתיב הענק`],
  [`Path of the Storm Herald`,`נתיב מבשר הסערה`],
  [`Path of the Totem Warrior`,`נתיב לוחם הטוטם`],
  [`Path of Wild Magic`,`נתיב הקסם הפראי`],
  [`Path of the Zealot`,`נתיב הקנאי`],
]);
heAdd([
  [`Rage`,`זעם`],
  [`Bonus action: advantage on STR checks & saves, bonus rage damage, resistance to bludgeoning/piercing/slashing. Not in heavy armor.`,`פעולת בונוס: יתרון בבדיקות ובהצלות כוח, נזק זעם נוסף, עמידות למוחץ/דוקר/חותך. לא בשריון כבד.`],
  [`Unarmored Defense (Barbarian)`,`הגנה ללא שריון (ברברי)`],
  [`While not wearing armor, AC = 10 + DEX mod + CON mod (shield allowed). Use the AC override in Inventory.`,`ללא שריון לבוש, AC = 10 + מודיפיקטור זריזות + מודיפיקטור חוסן (מגן מותר). יש להשתמש בעקיפת ה-AC בלשונית ציוד.`],
  [`Reckless Attack`,`התקפה פזיזה`],
  [`Advantage on melee STR attacks this turn; attacks against you have advantage until your next turn.`,`יתרון בהתקפות קרב קרוב מבוססות כוח בתור הזה; להתקפות נגדך יש יתרון עד התור הבא שלך.`],
  [`Danger Sense`,`חוש סכנה`],
  [`Advantage on DEX saves against effects you can see (traps, spells).`,`יתרון בהצלות זריזות מול אפקטים הנראים לעין (מלכודות, כישופים).`],
  [`Extra Attack`,`התקפה נוספת`],
  [`Attack twice when you take the Attack action.`,`התקפה פעמיים בעת ביצוע פעולת ההתקפה.`],
  [`Fast Movement`,`תנועה מהירה`],
  [`+10 ft. speed while not in heavy armor.`,`+10 רגל למהירות כל עוד לא בשריון כבד.`],
  [`Feral Instinct`,`אינסטינקט פראי`],
  [`Advantage on initiative rolls; act normally when surprised if you rage first.`,`יתרון בהטלות יוזמה; פעולה רגילה כשמופתעים אם נכנסים לזעם קודם.`],
  [`Brutal Critical`,`פגיעה קריטית אכזרית`],
  [`Roll one extra weapon damage die on a critical hit (two extra dice at 13th level, three at 17th).`,`הטלת קוביית נזק נשק נוספת אחת בפגיעה קריטית (שתי קוביות נוספות ברמה 13, שלוש ברמה 17).`],
  [`Primal Path`,`נתיב קדמון`],
  [`Choose your Primal Path (subclass): Ancestral Guardian, Battlerager, Beast, Berserker, Giant, Storm Herald, Totem Warrior, Wild Magic, or Zealot.`,`בחירת הנתיב הקדמון (תת-מקצוע): שומר האבות, רב-קרב, חיה, ברסרקר, ענק, מבשר הסערה, לוחם הטוטם, קסם פראי או קנאי.`],
  [`Relentless Rage`,`זעם בלתי נלאה`],
  [`When you drop to 0 HP while raging (and aren't killed outright), CON save (DC 10, +5 for each time you've used this since your last short/long rest) to drop to 1 HP instead.`,`כשיורדים ל-0 HP בזמן זעם (ולא נהרגים במקום), הצלת חוסן (DC 10, +5 על כל שימוש מאז המנוחה הקצרה/הארוכה האחרונה) כדי לרדת ל-1 HP במקום.`],
  [`Persistent Rage`,`זעם מתמיד`],
  [`Your rage no longer ends early on its own; it lasts until you choose to end it or you fall unconscious.`,`הזעם כבר לא מסתיים מוקדם מעצמו; הוא נמשך עד שבוחרים לסיימו או עד שנכנסים למצב מחוסר הכרה.`],
  [`Indomitable Might`,`עוצמה בלתי מנוצחת`],
  [`If your total for a Strength check is less than your Strength score, use your Strength score instead.`,`אם סך בדיקת כוח נמוך מציון הכוח, משתמשים בציון הכוח במקום.`],
  [`Primal Champion`,`אלוף קדמון`],
  [`Your Strength and Constitution scores each increase by 4 (max 24), and you can rage an unlimited number of times per day.`,`ציוני הכוח והחוסן עולים כל אחד ב-4 (מקסימום 24), ואפשר להיכנס לזעם ללא הגבלת מספר הפעמים ביום.`],
  [`Frenzy`,`טירוף`],
  [`While raging, bonus-action melee attack each turn; take 1 level of exhaustion when the rage ends.`,`בזמן זעם, התקפת קרב קרוב כפעולת בונוס בכל תור; מקבלים רמת תשישות אחת כשהזעם מסתיים.`],
  [`Mindless Rage`,`זעם חסר שכל`],
  [`Can't be charmed or frightened while raging (already charmed/frightened when you rage? no effect while raging).`,`אי אפשר להיות מכושף או מפוחד בזמן זעם (מי שכבר מכושף/מפוחד בכניסה לזעם — ללא השפעה בזמן הזעם).`],
  [`Intimidating Presence`,`נוכחות מאיימת`],
  [`Action: frighten one creature within 30 ft. (WIS save), for as long as you attack no one else.`,`פעולה: הפחדת יצור אחד בטווח 30 רגל (הצלת חוכמה), כל עוד לא תוקפים אחר.`],
  [`Retaliation`,`תגמול`],
  [`Reaction: melee attack a creature within 5 ft. that just damaged you.`,`תגובה: התקפת קרב קרוב על יצור בטווח 5 רגל שזה עתה פגע בך.`],
  [`Ancestral Protectors`,`מגיני האבות`],
  [`While raging, the first creature you hit each turn is haunted by spectral warriors: disadvantage on its attacks against anyone but you until your next turn, and any creature it hits gains resistance to that damage.`,`בזמן זעם, היצור הראשון שפוגעים בו בכל תור נרדף על ידי לוחמי רפאים: חיסרון בהתקפותיו נגד כל מי מלבדך עד התור הבא שלך, וכל יצור שהוא פוגע בו מקבל עמידות לנזק זה.`],
  [`Spirit Shield`,`מגן הרוחות`],
  [`While raging, reaction: reduce damage to a creature within 30 ft. by 2d6 (3d6 at 10th level, 4d6 at 14th).`,`בזמן זעם, תגובה: הפחתת הנזק ליצור בטווח 30 רגל ב-2d6 (3d6 ברמה 10, 4d6 ברמה 14).`],
  [`Consult the Spirits`,`התייעצות עם הרוחות`],
  [`Cast Augury or Clairvoyance (WIS-based, no slot or material cost), once per short/long rest.`,`הטלת קריאת סימנים או ראייה מרחוק (מבוסס חוכמה, ללא משבצת או עלות רכיב חומרי), פעם אחת בכל מנוחה קצרה/ארוכה.`],
  [`Vengeful Ancestors`,`אבות נוקמים`],
  [`When Spirit Shield reduces an attack's damage, the attacker takes that much force damage.`,`כשמגן הרוחות מפחית את נזק ההתקפה, התוקף סופג כמות זהה של נזק כוח.`],
  [`Battlerager Armor`,`שריון רב-הקרב`],
  [`While wearing spiked armor and raging: bonus action to attack with your armor spikes (1d4 piercing), and a successful grapple made with the Attack action deals 3 extra piercing damage.`,`בזמן לבישת שריון דורבנות ובזעם: פעולת בונוס להתקפה בדורבנות השריון (1d4 דוקר), ואחיזה מוצלחת בפעולת ההתקפה גורמת 3 נזק דוקר נוסף.`],
  [`Reckless Abandon`,`הפקרות פזיזה`],
  [`Using Reckless Attack while raging also grants temp HP equal to your CON mod (min 1); lost when the rage ends.`,`שימוש בהתקפה פזיזה בזמן זעם מעניק גם נקודות חיים זמניות כגובה מודיפיקטור החוסן (מינימום 1); הן אובדות כשהזעם מסתיים.`],
  [`Battlerager Charge`,`סערת רב-הקרב`],
  [`Bonus action to Dash while raging.`,`פעולת בונוס לדהירה בזמן זעם.`],
  [`Spiked Retribution`,`גמול דורבנים`],
  [`While raging, not incapacitated, and wearing spiked armor: a creature that hits you with a melee attack from 5 ft. away takes 3 piercing damage.`,`בזמן זעם, כשלא במצב חסר יכולת פעולה ובשריון דורבנות: יצור שפוגע בך בהתקפת קרב קרוב מטווח 5 רגל סופג 3 נזק דוקר.`],
  [`Form of the Beast`,`צורת החיה`],
  [`While raging, grow one natural weapon each rage: Bite (1d8 piercing; once/turn regain HP = proficiency bonus on a hit if below half HP), Claws (1d6 slashing; once/turn make an extra claw attack), or Tail (1d8 piercing, reach; reaction to add 1d8 to your AC against one attack from within 10 ft.).`,`בזמן זעם, גידול נשק טבעי אחד בכל זעם: נשיכה (1d8 דוקר; פעם בתור, החזר HP כגובה בונוס המיומנות בפגיעה אם מתחת לחצי HP), טפרים (1d6 חותך; פעם בתור התקפת טפרים נוספת), או זנב (1d8 דוקר, טווח; תגובה להוספת 1d8 ל-AC נגד התקפה אחת מטווח 10 רגל).`],
  [`Bestial Soul`,`נשמה חייתית`],
  [`Natural weapons count as magical for overcoming resistance/immunity. After a rest, pick one benefit until the next rest: swimming speed, climbing speed, or a longer jump.`,`הנשק הטבעי נחשב קסום להתגברות על עמידות/חסינות. אחרי מנוחה, בחירת יתרון אחד עד המנוחה הבאה: מהירות שחייה, מהירות טיפוס או קפיצה ארוכה יותר.`],
  [`Infectious Fury`,`זעם מדבק`],
  [`On a natural-weapon hit while raging, target makes a WIS save (DC 8 + proficiency + CON mod) or takes 2d12 psychic damage, or is forced to attack a creature of your choice with its reaction (your pick each time). Proficiency-bonus uses per long rest.`,`בפגיעת נשק טבעי בזמן זעם, המטרה מטילה הצלת חוכמה (DC 8 + מיומנות + מודיפיקטור חוסן) או סופגת 2d12 נזק נפשי, או נאלצת לתקוף יצור לבחירתך בתגובתה (הבחירה בכל פעם). מספר שימושים כבונוס המיומנות לכל מנוחה ארוכה.`],
  [`Call the Hunt`,`קריאה לציד`],
  [`On entering rage, mark willing creatures within 30 ft. (max = CON mod): you gain 5 temp HP per creature marked, and each adds a d6 to one of its damage rolls per turn. Proficiency-bonus uses per long rest.`,`בכניסה לזעם, סימון יצורים מרצון בטווח 30 רגל (מקסימום כמודיפיקטור החוסן): מקבלים 5 נקודות חיים זמניות לכל יצור מסומן, וכל אחד מוסיף d6 להטלת נזק אחת שלו בכל תור. מספר שימושים כבונוס המיומנות לכל מנוחה ארוכה.`],
  [`Giant's Power`,`כוחו של הענק`],
  [`Learn to speak/read/write Giant (or another language if you already know it) and learn the druidcraft or thaumaturgy cantrip.`,`לימוד דיבור/קריאה/כתיבה בשפת הענקים (או שפה אחרת אם כבר יודעים אותה) ולימוד הקנטריפ מלאכת הדרואיד או מעשי פלאים.`],
  [`Giant's Havoc`,`הרס הענק`],
  [`While raging: add your Rage Damage bonus to a Strength-based thrown-weapon attack, and your reach increases by 5 ft. — becoming Large if you're smaller (with your gear).`,`בזמן זעם: הוספת בונוס נזק הזעם להתקפת נשק זריקה מבוססת כוח, והטווח גדל ב-5 רגל — והגודל הופך ל"גדול" אם הוא קטן יותר (כולל הציוד).`],
  [`Elemental Cleaver`,`מבתר יסודי`],
  [`On entering rage, infuse a held weapon with acid, cold, fire, lightning, or thunder: +1d6 damage of that type on a hit, and it gains the thrown property (range 20/60).`,`בכניסה לזעם, הקסמת נשק מוחזק בחומצה, קור, אש, ברק או רעם: +1d6 נזק מאותו סוג בפגיעה, והוא מקבל את תכונת הזריקה (טווח 20/60).`],
  [`Mighty Impel`,`דחף אדיר`],
  [`Bonus action while raging: move a Medium or smaller creature within your reach to an unoccupied space within 30 ft.; an unwilling target gets a STR save (DC 8 + proficiency + STR mod).`,`פעולת בונוס בזמן זעם: העברת יצור בגודל בינוני או קטן יותר שבטווח ההשגה למשבצת פנויה בטווח 30 רגל; מטרה שאינה מרצון מקבלת הצלת כוח (DC 8 + מיומנות + מודיפיקטור כוח).`],
  [`Demiurgic Colossus`,`קולוסוס יוצר`],
  [`While raging, reach +10 ft., you can grow to Large or Huge, Mighty Impel can move Large creatures, and Elemental Cleaver's bonus damage becomes 2d6.`,`בזמן זעם, טווח +10 רגל, אפשר לגדול לגודל גדול או ענק, דחף אדיר יכול להעביר יצורים גדולים, ונזק הבונוס של מבתר יסודי הופך ל-2d6.`],
  [`Storm Aura`,`הילת סערה`],
  [`While raging, a 10-ft. aura (on when you rage, reactivate as a bonus action) whose effect depends on an environment fixed at 3rd level — desert (2 fire damage to others in it, growing with level), sea (one creature saves or takes 1d6 lightning, growing), or tundra (grant 2 temp HP, growing). Save DC = 8 + proficiency + CON mod.`,`בזמן זעם, הילה של 10 רגל (פעילה בכניסה לזעם, מופעלת מחדש בפעולת בונוס) שהאפקט שלה תלוי בסביבה שנקבעת ברמה 3 — מדבר (2 נזק אש לאחרים בה, גדל עם הרמה), ים (יצור אחד מטיל הצלה או סופג 1d6 ברק, גדל), או טונדרה (הענקת 2 נקודות חיים זמניות, גדל). DC הצלה = 8 + מיומנות + מודיפיקטור חוסן.`],
  [`Storm Soul`,`נשמת הסערה`],
  [`Permanent benefit tied to your environment: desert (fire resistance, immune to extreme heat, ignite objects), sea (lightning resistance, water breathing, 30 ft. swim speed), or tundra (cold resistance, immune to extreme cold, freeze water).`,`יתרון קבוע הקשור לסביבה: מדבר (עמידות לאש, חסינות לחום קיצוני, הצתת חפצים), ים (עמידות לברק, נשימת מים, מהירות שחייה 30 רגל), או טונדרה (עמידות לקור, חסינות לקור קיצוני, הקפאת מים).`],
  [`Shielding Storm`,`סערה מגינה`],
  [`Extend your Storm Soul resistance to any creature of your choice while it stands in your Storm Aura.`,`הרחבת העמידות של נשמת הסערה לכל יצור לבחירתך כל עוד הוא עומד בהילת הסערה.`],
  [`Raging Storm`,`סערה משתוללת`],
  [`Environment-based reaction: desert (attacker fails a DEX save, takes fire damage = half your barbarian level), sea (a creature you hit fails a STR save and is knocked prone), or tundra (Storm Aura activation forces a STR save or the target's speed drops to 0).`,`תגובה לפי הסביבה: מדבר (תוקף שנכשל בהצלת זריזות סופג נזק אש כחצי מרמת הברברי), ים (יצור שפוגעים בו נכשל בהצלת כוח ונופל שרוע), או טונדרה (הפעלת הילת הסערה מכריחה הצלת כוח או שמהירות המטרה יורדת ל-0).`],
  [`Spirit Seeker`,`מחפש הרוחות`],
  [`Cast Beast Sense and Speak with Animals, but only as rituals.`,`הטלת חושי חיה ודיבור עם חיות, אך רק כטקסים.`],
  [`Totem Spirit`,`רוח הטוטם`],
  [`Choose a totem animal: Bear, Eagle, Elk, Tiger, or Wolf.`,`בחירת חיית טוטם: דוב, נשר, איל, נמר או זאב.`],
  [`Totem Spirit: Bear`,`רוח הטוטם: דוב`],
  [`While raging, resistance to all damage except psychic.`,`בזמן זעם, עמידות לכל סוגי הנזק מלבד נפשי.`],
  [`Totem Spirit: Eagle`,`רוח הטוטם: נשר`],
  [`While raging without heavy armor, others have disadvantage on opportunity attacks against you and you can Dash as a bonus action.`,`בזמן זעם ללא שריון כבד, לאחרים חיסרון בהתקפות הזדמנות נגדך ואפשר לדהור כפעולת בונוס.`],
  [`Totem Spirit: Elk`,`רוח הטוטם: איל`],
  [`While raging without heavy armor, your speed increases by 15 ft.`,`בזמן זעם ללא שריון כבד, המהירות גדלה ב-15 רגל.`],
  [`Totem Spirit: Tiger`,`רוח הטוטם: נמר`],
  [`While raging, +10 ft. to your long jump distance and +3 ft. to your high jump distance.`,`בזמן זעם, +10 רגל למרחק קפיצה לרוחק, וגם +3 רגל לגובה קפיצה לגובה.`],
  [`Totem Spirit: Wolf`,`רוח הטוטם: זאב`],
  [`While raging, friends have advantage on melee attack rolls against any creature within 5 ft. of you that's hostile to you.`,`בזמן זעם, לחברים יתרון בהטלות התקפת קרב קרוב נגד כל יצור עוין בטווח 5 רגל ממך.`],
  [`Aspect of the Beast`,`פן החיה`],
  [`Aspect of the Beast: Bear`,`פן החיה: דוב`],
  [`Double carrying capacity; advantage on STR checks to push, pull, lift, or break objects.`,`קיבולת נשיאה כפולה; יתרון בבדיקות כוח לדחיפה, משיכה, הרמה או שבירה של חפצים.`],
  [`Aspect of the Beast: Eagle`,`פן החיה: נשר`],
  [`See up to 1 mile with no difficulty; dim light no longer gives disadvantage on Perception checks.`,`ראייה עד מייל אחד ללא קושי; אור עמום כבר לא גורם לחיסרון בבדיקות תפיסה.`],
  [`Aspect of the Beast: Elk`,`פן החיה: איל`],
  [`Double your travel pace for up to ten companions within 60 ft. of you.`,`הכפלת קצב המסע של עד עשרה בני לוויה בטווח 60 רגל.`],
  [`Aspect of the Beast: Tiger`,`פן החיה: נמר`],
  [`Proficiency in two of Athletics, Acrobatics, Stealth, Survival — add the matching skill effects.`,`מיומנות בשניים מתוך אתלטיקה, אקרובטיקה, התגנבות, הישרדות — הוספת השפעות הכישורים המתאימים.`],
  [`Aspect of the Beast: Wolf`,`פן החיה: זאב`],
  [`Track creatures while traveling at a fast pace, and move stealthily at a normal pace.`,`מעקב אחר יצורים בעת נסיעה בקצב מהיר, ותנועה בהתגנבות בקצב רגיל.`],
  [`Spirit Walker`,`הולך עם הרוחות`],
  [`Cast Commune with Nature as a ritual; a spirit of your totem animal delivers the answers to you.`,`הטלת התייעצות עם הטבע כטקס; רוח של חיית הטוטם מוסרת את התשובות.`],
  [`Totemic Attunement`,`התאמה טוטמית`],
  [`Totemic Attunement: Bear`,`התאמה טוטמית: דוב`],
  [`While raging, hostile creatures within 5 ft. of you have disadvantage on attack rolls against anyone but you.`,`בזמן זעם, ליצורים עוינים בטווח 5 רגל חיסרון בהטלות התקפה נגד כל מי מלבדך.`],
  [`Totemic Attunement: Eagle`,`התאמה טוטמית: נשר`],
  [`While raging, flying speed equal to your walking speed (you fall if you end your turn airborne).`,`בזמן זעם, מהירות מעוף השווה למהירות ההליכה (נופלים אם מסיימים את התור באוויר).`],
  [`Totemic Attunement: Elk`,`התאמה טוטמית: איל`],
  [`While raging, you can move through a Large or smaller creature's space; it makes a STR save (DC 8 + STR mod + proficiency) or is knocked prone and takes 1d12 + STR mod bludgeoning damage.`,`בזמן זעם, אפשר לעבור דרך שטחו של יצור גדול או קטן יותר; הוא מטיל הצלת כוח (DC 8 + מודיפיקטור כוח + מיומנות) או נופל שרוע וסופג 1d12 + מודיפיקטור כוח נזק מוחץ.`],
  [`Totemic Attunement: Tiger`,`התאמה טוטמית: נמר`],
  [`While raging, after moving 20+ ft. in a straight line toward a creature, make one additional melee attack against it.`,`בזמן זעם, אחרי תנועה של 20 רגל ויותר בקו ישר לעבר יצור, התקפת קרב קרוב נוספת אחת נגדו.`],
  [`Totemic Attunement: Wolf`,`התאמה טוטמית: זאב`],
  [`While raging, a Large or smaller creature you hit with a melee weapon attack can be knocked prone.`,`בזמן זעם, יצור גדול או קטן יותר שפוגעים בו בהתקפת נשק קרב קרוב יכול ליפול שרוע.`],
  [`Magic Awareness`,`מודעות לקסם`],
  [`Action: sense the location of any spell or magic item within 60 ft. (not behind total cover) until the end of your next turn. Proficiency-bonus uses per long rest.`,`פעולה: חישת מיקום של כל כישוף או פריט קסום בטווח 60 רגל (שלא מאחורי מחסה מלא) עד סוף התור הבא. מספר שימושים כבונוס המיומנות לכל מנוחה ארוכה.`],
  [`Wild Surge`,`גל פראי`],
  [`On entering rage, roll a random effect off the Wild Magic Surge table (temp HP + necrotic damage, teleport, a force-damage burst, a weapon that deals force damage, retaliatory force damage, an AC buff aura, difficult terrain, or a self-blinding light burst). Save DC = 8 + proficiency + CON mod.`,`בכניסה לזעם, הטלת אפקט אקראי מטבלת גל הקסם הפראי (נקודות חיים זמניות + נזק נקרוטי, טלפורטציה, פרץ נזק כוח, נשק שגורם נזק כוח, נזק כוח כתגמול, הילה המחזקת AC, שטח קשה, או פרץ אור מסנוור את המטיל). DC הצלה = 8 + מיומנות + מודיפיקטור חוסן.`],
  [`Bolstering Magic`,`קסם מחזק`],
  [`Touch a creature: it rolls a d3, adding it to its next attack roll or ability check, or regaining an expended spell slot of that level or lower. Proficiency-bonus uses per long rest.`,`מגע ביצור: הוא מטיל d3 ומוסיף אותו להטלת ההתקפה או לבדיקת התכונה הבאה שלו, או משיב משבצת כישוף שהוצאה מאותה רמה או נמוכה. מספר שימושים כבונוס המיומנות לכל מנוחה ארוכה.`],
  [`Unstable Backlash`,`תגובת נגד לא יציבה`],
  [`Reaction, when you take damage or fail a save while raging: reroll on the Wild Magic Surge table, replacing your current active surge effect with the new result.`,`תגובה, כשסופגים נזק או נכשלים בהצלה בזמן זעם: הטלה חוזרת בטבלת גל הקסם הפראי, והחלפת האפקט הפעיל הנוכחי בתוצאה החדשה.`],
  [`Controlled Surge`,`גל מבוקר`],
  [`Whenever you roll on the Wild Magic Surge table, roll twice and choose which result to apply.`,`בכל פעם שמטילים בטבלת גל הקסם הפראי, מטילים פעמיים ובוחרים איזו תוצאה להחיל.`],
  [`Divine Fury`,`זעם אלוהי`],
  [`The first creature you hit each turn with a weapon attack takes extra necrotic or radiant damage (your choice, fixed at 3rd level) equal to 1d6 + half your barbarian level.`,`היצור הראשון שפוגעים בו בכל תור בהתקפת נשק סופג נזק נקרוטי או זוהר נוסף (לבחירתך, נקבע ברמה 3) השווה ל-1d6 + חצי מרמת הברברי.`],
  [`Warrior of the Gods`,`לוחם האלים`],
  [`A spell whose sole effect is restoring you to life (such as Raise Dead) can be cast on you with no material component cost.`,`אפשר להטיל עליך כישוף שהאפקט היחיד שלו הוא החזרה לחיים (כמו החזרת מתים) ללא עלות רכיב חומרי.`],
  [`Fanatical Focus`,`מיקוד קנאי`],
  [`Once per rage, reroll a failed saving throw made while raging (you must use the new roll).`,`פעם אחת בכל זעם, הטלה חוזרת של הטלת הצלה שנכשלה בזמן הזעם (חובה להשתמש בהטלה החדשה).`],
  [`Zealous Presence`,`נוכחות קנאית`],
  [`Bonus action: up to ten allies within 60 ft. who can hear you gain advantage on attack rolls and saving throws until the start of your next turn.`,`פעולת בונוס: עד עשרה בעלי ברית בטווח 60 רגל שיכולים לשמוע מקבלים יתרון בהטלות התקפה והטלות הצלה עד תחילת התור הבא שלך.`],
  [`Rage Beyond Death`,`זעם מעבר למוות`],
  [`While raging, dropping to 0 HP doesn't knock you unconscious; you still make death saves, but can't die from failing them until your rage ends.`,`בזמן זעם, ירידה ל-0 HP לא מפילה אותך מחוסר הכרה; ממשיכים להטיל הצלות מוות, אבל אי אפשר למות מכישלון בהן עד שהזעם מסתיים.`],
]);

// ================= Blood Hunter =================
heAdd([
  [`Order of the Mutant`,`מסדר המוטנט`],
  [`Order of the Ghostslayer`,`מסדר קוטל הרוחות`],
  [`Order of the Lycan`,`מסדר הליקן`],
  [`Order of the Profane Soul`,`מסדר הנשמה הטמאה`],
]);
heAdd([
  [`Hunter's Bane`,`קללת הצייד`],
  [`Advantage on Survival checks to track, and Intelligence checks to recall lore about, fey, fiends, and undead. Your hemocraft save DC uses Intelligence.`,`יתרון בבדיקות הישרדות למעקב, ובבדיקות אינטליגנציה להיזכרות בידע על יצורי פיות, שדים ובלתי-מתים. ה-DC של הצלות אמנות הדם משתמש באינטליגנציה.`],
  [`Blood Maledict`,`קללת דם`],
  [`Bonus action: afflict a creature within 30 ft. with one of two blood curses you know; amplify it by taking necrotic damage equal to half your Blood Hunter level for a stronger effect. 1/rest (2 at 6th, 3 at 13th, 4 at 17th).`,`פעולת בונוס: הטלת אחת משתי קללות דם שידועות על יצור בטווח 30 רגל; אפשר להעצים אותה בספיגת נזק נקרוטי כחצי מרמת צייד הדם לאפקט חזק יותר. פעם אחת למנוחה (2 ברמה 6, 3 ברמה 13, 4 ברמה 17).`],
  [`Blood Curse of Binding`,`קללת דם: כבילה`],
  [`Blood Maledict: a Large or smaller creature within 30 ft. fails a STR save or its speed becomes 0 and it can't take reactions until the end of your next turn. Amplify: works on any size, lasts 1 minute, repeat save each turn.`,`קללת דם: יצור גדול או קטן יותר בטווח 30 רגל נכשל בהצלת כוח, או שמהירותו הופכת ל-0 והוא לא יכול לבצע תגובות עד סוף התור הבא שלך. העצמה: פועלת על כל גודל, נמשכת דקה אחת, הצלה חוזרת בכל תור.`],
  [`Blood Curse of Bloated Agony`,`קללת דם: ייסורי נפיחות`],
  [`Blood Maledict: a creature within 30 ft. has disadvantage on STR and DEX checks, and takes 1d8 necrotic damage if it makes more than one attack on its turn. Amplify: lasts 1 minute, CON save each turn to end early.`,`קללת דם: ליצור בטווח 30 רגל חיסרון בבדיקות כוח וזריזות, והוא סופג 1d8 נזק נקרוטי אם הוא מבצע יותר מהתקפה אחת בתורו. העצמה: נמשכת דקה אחת, הצלת חוסן בכל תור כדי לסיים מוקדם.`],
  [`Blood Curse of Exposure`,`קללת דם: חשיפה`],
  [`Blood Maledict (reaction): when a creature within 30 ft. takes damage, it loses resistance to that damage type until the end of its next turn. Amplify: strips immunity to that damage type instead.`,`קללת דם (תגובה): כשיצור בטווח 30 רגל סופג נזק, הוא מאבד עמידות לסוג הנזק הזה עד סוף תורו הבא. העצמה: מסירה חסינות לסוג הנזק הזה במקום.`],
  [`Blood Curse of the Eyeless`,`קללת דם: חסר העיניים`],
  [`Blood Maledict (reaction): when a creature within 30 ft. makes an attack roll, subtract your hemocraft die from it. Amplify: applies to every attack roll it makes until the end of its turn.`,`קללת דם (תגובה): כשיצור בטווח 30 רגל מטיל הטלת התקפה, מפחיתים ממנה את קוביית אמנות הדם. העצמה: חלה על כל הטלת התקפה שלו עד סוף תורו.`],
  [`Blood Curse of the Marked`,`קללת דם: המסומן`],
  [`Blood Maledict: a creature within 30 ft. takes an extra hemocraft die of rite damage the next time your active Crimson Rite hits it this turn. Amplify: your next attack against it has advantage before the end of your turn.`,`קללת דם: יצור בטווח 30 רגל סופג קוביית נזק פולחן נוספת מאמנות הדם בפעם הבאה שהפולחן הארגמן הפעיל פוגע בו בתור הזה. העצמה: להתקפה הבאה נגדו יש יתרון לפני סוף התור.`],
  [`Blood Curse of the Muddled Mind`,`קללת דם: התודעה המבולבלת`],
  [`Blood Maledict: a concentrating creature within 30 ft. has disadvantage on its next Constitution save to maintain concentration. Amplify: disadvantage on every concentration save it makes until the end of your next turn.`,`קללת דם: ליצור מרוכז בטווח 30 רגל חיסרון בהצלת החוסן הבאה שלו לשמירה על ריכוז. העצמה: חיסרון בכל הצלת ריכוז שלו עד סוף התור הבא שלך.`],
  [`Crimson Rite`,`פולחן ארגמן`],
  [`Bonus action: imbue a weapon you're holding with an elemental rite, adding rite damage on hit; you take necrotic damage at the start of each of your turns while it's active. Extra rites known at 7th & 14th.`,`פעולת בונוס: הקסמת נשק מוחזק בפולחן יסודי, המוסיף נזק פולחן בפגיעה; סופגים נזק נקרוטי בתחילת כל תור כל עוד הוא פעיל. פולחנים נוספים ידועים ברמות 7 ו-14.`],
  [`Fighting Style (Blood Hunter)`,`סגנון לחימה (צייד דם)`],
  [`Choose one: Archery, Dueling, Great Weapon Fighting, or Two-Weapon Fighting.`,`בחירה באחד: קשתות, דו-קרב, לחימה בנשק גדול או לחימה בשני נשקים.`],
  [`Archery`,`קשתות`],
  [`+2 bonus to attack rolls you make with ranged weapons.`,`בונוס +2 להטלות התקפה בנשק טווח.`],
  [`Dueling`,`דו-קרב`],
  [`+2 bonus to damage rolls when wielding a melee weapon in one hand and no other weapon.`,`בונוס +2 להטלות נזק כשאוחזים נשק קרב קרוב ביד אחת ואין נשק אחר.`],
  [`Great Weapon Fighting`,`לחימה בנשק גדול`],
  [`When you roll a 1 or 2 on a damage die for a two-handed or versatile melee weapon, reroll it and use the new roll — even if it's a 1 or 2.`,`כשמטילים 1 או 2 בקוביית נזק של נשק קרב קרוב דו-ידני או רב-שימושי, מטילים שוב ומשתמשים בתוצאה החדשה — גם אם היא 1 או 2.`],
  [`Two-Weapon Fighting`,`לחימה בשני נשקים`],
  [`Add your ability modifier to the damage of your off-hand attack when fighting with two weapons.`,`הוספת מודיפיקטור התכונה לנזק של התקפת היד המשנית בלחימה בשני נשקים.`],
  [`Extra Attack (Blood Hunter)`,`התקפה נוספת (צייד דם)`],
  [`Brand of Castigation`,`סימן העונש`],
  [`On a hit with an active Crimson Rite weapon, brand the creature: you always know its direction, and it takes psychic damage equal to your hemocraft modifier whenever it damages you or a creature within 5 ft. of you.`,`בפגיעה בנשק עם פולחן ארגמן פעיל, סימון היצור: הכיוון שלו ידוע תמיד, והוא סופג נזק נפשי כגובה מודיפיקטור אמנות הדם בכל פעם שהוא פוגע בך או ביצור בטווח 5 רגל ממך.`],
  [`Grim Psychometry`,`פסיכומטריה קודרת`],
  [`Touch an object or place to sense sinister history tied to it — advantage on the History check, with a chance of a brief vision.`,`מגע בחפץ או במקום כדי לחוש היסטוריה מאיימת הקשורה אליו — יתרון בבדיקת היסטוריה, עם סיכוי לחזון קצר.`],
  [`Dark Augmentation`,`העצמה אפלה`],
  [`+5 ft. speed, and advantage on Strength, Dexterity, and Constitution saving throws.`,`+5 רגל למהירות, ויתרון בהטלות הצלה של כוח, זריזות וחוסן.`],
  [`Blood Hunter Order`,`מסדר צייד הדם`],
  [`Choose your Blood Hunter Order (subclass): Ghostslayer, Lycan, Mutant, or Profane Soul.`,`בחירת מסדר צייד הדם (תת-מקצוע): קוטל רוחות, ליקן, מוטנט או נשמה טמאה.`],
  [`Brand of Tethering`,`סימן הקשירה`],
  [`Brand of Castigation's backlash damage doubles to twice your hemocraft modifier; a creature you've branded can't Dash, and teleporting away deals it 4d6 psychic damage unless it succeeds on a Wisdom save.`,`נזק התגובה של סימן העונש מוכפל לפי שניים ממודיפיקטור אמנות הדם; יצור מסומן לא יכול לדהור, וטלפורטציה ממנו גורמת לו 4d6 נזק נפשי אלא אם הוא מצליח בהצלת חוכמה.`],
  [`Hardened Soul`,`נשמה מוקשחת`],
  [`Advantage on saving throws against being charmed or frightened.`,`יתרון בהטלות הצלה מפני מצב מכושף או מפוחד.`],
  [`Sanguine Mastery`,`שליטה בדם`],
  [`Once per turn, reroll a hemocraft damage die. Whenever you score a critical hit with a weapon carrying an active Crimson Rite, regain one expended use of Blood Maledict.`,`פעם בתור, הטלה חוזרת של קוביית נזק של אמנות הדם. בכל פעם שמבצעים פגיעה קריטית בנשק עם פולחן ארגמן פעיל, משיבים שימוש אחד שהוצא בקללת דם.`],
  [`Mutagencraft`,`אמנות המוטגנים`],
  [`Learn 4 mutagen formulas (more at higher levels); bonus action to concoct one after a short/long rest, altering your mental or physical abilities at the cost of a risky side effect.`,`לימוד 4 נוסחאות מוטגן (עוד ברמות גבוהות יותר); פעולת בונוס להכנת אחת אחרי מנוחה קצרה/ארוכה, המשנה יכולות מנטליות או פיזיות במחיר תופעת לוואי מסוכנת.`],
  [`Strange Metabolism`,`חילוף חומרים מוזר`],
  [`Immune to poison damage and the poisoned condition. Bonus action: ignore a mutagen's negative side effect for 1 minute, once per long rest.`,`חסינות לנזק רעל ולמצב מורעל. פעולת בונוס: התעלמות מתופעת הלוואי השלילית של מוטגן למשך דקה אחת, פעם אחת בכל מנוחה ארוכה.`],
  [`Brand of Axiom`,`סימן האקסיומה`],
  [`Branding a creature with Brand of Castigation ends illusions/invisibility on it and blocks new ones; it must succeed a WIS save or revert from an altered/alternate form and be stunned.`,`סימון יצור בסימן העונש מסיים עליו אשליות/בלתי נראות וחוסם חדשות; הוא חייב להצליח בהצלת חוכמה או שיחזור מצורה משונה/חלופית ויהיה המום.`],
  [`Blood Curse of Corrosion`,`קללת דם: שחיקה`],
  [`Gain the Blood Curse of Corrosion for Blood Maledict, infusing a creature's body with terrible toxins; doesn't count against your curses known.`,`קבלת קללת דם: שחיקה עבור קללת דם, המחדירה לגוף היצור רעלנים נוראיים; לא נספרת במניין הקללות הידועות.`],
  [`Exalted Mutation`,`מוטציה נשגבת`],
  [`Bonus action: end one active mutagen and immediately concoct a different known mutagen for free. Hemocraft modifier uses per long rest.`,`פעולת בונוס: סיום מוטגן פעיל אחד והכנה מיידית של מוטגן ידוע אחר בחינם. מספר שימושים כמודיפיקטור אמנות הדם לכל מנוחה ארוכה.`],
  [`Rite of the Dawn`,`פולחן השחר`],
  [`Your active Crimson Rite deals radiant damage instead of its usual type, sheds bright light in a 20-ft. radius, grants resistance to necrotic damage, and adds an extra hemocraft die when it hits an undead creature.`,`הפולחן הארגמן הפעיל גורם נזק זוהר במקום הסוג הרגיל שלו, פולט אור בהיר ברדיוס 20 רגל, מעניק עמידות לנזק נקרוטי, ומוסיף קוביית אמנות הדם נוספת כשהוא פוגע ביצור בלתי-מת.`],
  [`Curse Specialist`,`מומחה קללות`],
  [`Gain one additional use of Blood Maledict, and your blood curses now affect any creature regardless of whether it has blood.`,`שימוש נוסף אחד בקללת דם, וקללות הדם משפיעות כעת על כל יצור, גם אם אין לו דם.`],
  [`Aether Walk`,`הליכה באתר`],
  [`Bonus action: step partway into the Ethereal Plane for a number of rounds equal to your hemocraft modifier (minimum 1), moving through creatures/objects as difficult terrain and affecting ethereal creatures; ending your turn inside an object deals 1d10 force damage. 1/rest (2 at 15th).`,`פעולת בונוס: כניסה חלקית למישור האתרי למשך מספר סבבים כמודיפיקטור אמנות הדם (מינימום 1), תנועה דרך יצורים/חפצים כשטח קשה ופגיעה ביצורים אתריים; סיום התור בתוך חפץ גורם 1d10 נזק כוח. פעם אחת למנוחה (2 ברמה 15).`],
  [`Brand of Sundering`,`סימן הפיצול`],
  [`Hits with an active Crimson Rite weapon deal an extra hemocraft die of damage, and a creature branded by you can't use incorporeal movement to pass through creatures or objects.`,`פגיעות בנשק עם פולחן ארגמן פעיל גורמות קוביית נזק נוספת של אמנות הדם, ויצור מסומן אינו יכול להשתמש בתנועה חסרת גוף כדי לעבור דרך יצורים או חפצים.`],
  [`Blood Curse of the Exorcist`,`קללת דם: מגרש השדים`],
  [`Gain the Blood Curse of the Exorcist for Blood Maledict, a curse tuned against undead and fiends; doesn't count against your curses known.`,`קבלת קללת דם: מגרש השדים עבור קללת דם, קללה המכוונת נגד בלתי-מתים ושדים; לא נספרת במניין הקללות הידועות.`],
  [`Rite Revival`,`תחיית הפולחן`],
  [`If you have an active Crimson Rite when you'd be reduced to 0 HP without dying outright, you can end all active rites to drop to 1 HP instead.`,`אם יש פולחן ארגמן פעיל כשאמורים לרדת ל-0 HP בלי למות במקום, אפשר לסיים את כל הפולחנים הפעילים כדי לרדת ל-1 HP במקום.`],
  [`Heightened Senses`,`חושים מחודדים`],
  [`Advantage on Wisdom (Perception) checks that rely on hearing or smell.`,`יתרון בבדיקות חוכמה (תפיסה) המסתמכות על שמיעה או ריח.`],
  [`Hybrid Transformation`,`התמרה היברידית`],
  [`Bonus action: assume a bestial hybrid form for up to 1 hour, 1/rest. While transformed: advantage on Strength checks/saves; +1 melee damage (+2 at 11th, +3 at 18th); resistance to nonmagical bludgeoning/piercing/slashing (not silvered); +1 AC without heavy armor; Crimson Rite can apply to your unarmed strikes (1d6, 1d8 at 11th); an extra unarmed strike with your Attack action. Dropping below half HP forces a DC 8 WIS save or you move toward and attack the nearest creature.`,`פעולת בונוס: קבלת צורה היברידית חייתית עד שעה אחת, פעם אחת למנוחה. בזמן ההתמרה: יתרון בבדיקות/הצלות כוח; +1 נזק קרב קרוב (+2 ברמה 11, +3 ברמה 18); עמידות למוחץ/דוקר/חותך לא קסום (לא מכוסף); +1 ל-AC ללא שריון כבד; פולחן ארגמן יכול לחול על מכות ללא נשק (1d6, 1d8 ברמה 11); מכה נוספת ללא נשק בפעולת ההתקפה. ירידה מתחת לחצי HP גורמת להצלת חוכמה DC 8 או שנעים לעבר היצור הקרוב ביותר ותוקפים אותו.`],
  [`Stalker's Prowess`,`כושר הצייד`],
  [`+10 ft. speed, +10 ft. long jump/+3 ft. high jump, and a growing bonus to unarmed attack rolls (+1, +2 at 11th, +3 at 18th); Crimson Rites active on your unarmed strikes count as magical.`,`+10 רגל למהירות, +10 רגל לקפיצה לרוחק/+3 רגל לקפיצה לגובה, ובונוס גדל להטלות התקפה ללא נשק (+1, +2 ברמה 11, +3 ברמה 18); פולחן ארגמן פעיל על מכות ללא נשק נחשב קסום.`],
  [`Advanced Transformation`,`התמרה מתקדמת`],
  [`Hybrid Transformation now recharges twice per short/long rest, and while below half HP in hybrid form you regain 1 + CON modifier (minimum 1) HP at the start of each of your turns.`,`התמרה היברידית נטענת כעת פעמיים בכל מנוחה קצרה/ארוכה, ובזמן ירידה מתחת לחצי HP בצורה ההיברידית משיבים 1 + מודיפיקטור חוסן (מינימום 1) HP בתחילת כל תור.`],
  [`Brand of the Voracious`,`סימן הרעבתן`],
  [`Advantage on the saving throw Hybrid Transformation forces when you drop below half HP, and advantage on attack rolls against creatures branded by you while transformed.`,`יתרון בהצלה שהתמרה היברידית כופה בירידה מתחת לחצי HP, ויתרון בהטלות התקפה נגד יצורים מסומנים בזמן ההתמרה.`],
  [`Hybrid Transformation Mastery`,`שליטה בהתמרה היברידית`],
  [`Hybrid Transformation no longer has a use limit or 1-hour cap — stay transformed until you choose to revert.`,`להתמרה היברידית אין עוד הגבלת שימושים או תקרת שעה אחת — אפשר להישאר מומרים עד שבוחרים לחזור.`],
  [`Blood Curse of the Howl`,`קללת דם: היללה`],
  [`Gain the Blood Curse of the Howl for Blood Maledict, a terrifying howl that can frighten foes near you; doesn't count against your curses known.`,`קבלת קללת דם: היללה עבור קללת דם, יללה מבעיתה שיכולה להפחיד אויבים קרובים; לא נספרת במניין הקללות הידועות.`],
  [`Profane Soul Spellcasting`,`הטלת כישופי נשמה טמאה`],
  [`Learn 2 warlock cantrips and 2 1st-level warlock spells, and gain 1 warlock-style spell slot (more at higher levels); your hemocraft ability (INT or WIS, your choice) is your spellcasting ability.`,`לימוד 2 קנטריפים של וורלוק ו-2 כישופי וורלוק מרמה 1, וקבלת משבצת כישוף אחת בסגנון וורלוק (עוד ברמות גבוהות יותר); תכונת אמנות הדם (אינטליגנציה או חוכמה, לבחירתך) היא תכונת הטלת הכישופים.`],
  [`Otherworldly Patron (Blood Hunter)`,`פטרון מעולם אחר (צייד דם)`],
  [`Choose a warlock-style patron (Archfey, Celestial, Fathomless, Fiend, Genie, Great Old One, Hexblade, Undead, or Undying) — it determines your Rite Focus benefit.`,`בחירת פטרון בסגנון וורלוק (ארכי-פיה, שמימי, עמקי הים, שד, ג'יני, הקדמון הגדול, להב המארה, בלתי-מת או בלתי-גוסס) — הוא קובע את יתרון מיקוד הפולחן.`],
  [`Rite Focus`,`מיקוד פולחן`],
  [`While a Crimson Rite is active, your weapon doubles as a spellcasting focus for your warlock spells and grants a benefit keyed to your chosen patron (a debuff, healing, or a defensive edge, among others).`,`כל עוד פולחן ארגמן פעיל, הנשק משמש גם כמוקד הטלת כישופים לכישופי הוורלוק ומעניק יתרון הקשור לפטרון שנבחר (החלשה, ריפוי או יתרון הגנתי, בין היתר).`],
  [`Mystic Frenzy`,`טירוף מיסטי`],
  [`Whenever you use your action to cast a cantrip, you can make one weapon attack as a bonus action.`,`בכל פעם שמשתמשים בפעולה כדי להטיל קנטריפ, אפשר לבצע התקפת נשק אחת כפעולת בונוס.`],
  [`Revealed Arcana`,`ארקנה חשופה`],
  [`Once per long rest, cast one patron-specific spell (e.g. Scorching Ray, Lesser Restoration, Branding Smite) without expending a spell slot.`,`פעם בכל מנוחה ארוכה, הטלת כישוף אחד ייחודי לפטרון (למשל קרן צורבת, שיקום קל, מכת סימון) בלי להוציא משבצת כישוף.`],
  [`Brand of the Sapping Scar`,`סימן הצלקת המחלישה`],
  [`A creature branded by you has disadvantage on saving throws against your warlock spells.`,`ליצור מסומן יש חיסרון בהטלות הצלה מפני כישופי הוורלוק.`],
  [`Unsealed Arcana`,`ארקנה פתוחה`],
  [`Gain a second patron-specific spell (e.g. Fireball, Haste, Revivify) castable once per long rest without a spell slot.`,`קבלת כישוף שני ייחודי לפטרון (למשל כדור אש, זירוז, החייאה) להטלה פעם בכל מנוחה ארוכה בלי משבצת כישוף.`],
  [`Blood Curse of the Souleater`,`קללת דם: אוכל הנשמות`],
  [`Gain the Blood Curse of the Soul Eater for Blood Maledict, siphoning life from a cursed creature; doesn't count against your curses known.`,`קבלת קללת דם: אוכל הנשמות עבור קללת דם, ושאיבת חיים מיצור מקולל; לא נספרת במניין הקללות הידועות.`],
]);

